        collections: vec![
            CollectionDescription { name: "arxiv-title".to_string(), },
            CollectionDescription { name: "arxiv-abstract".to_string(), },
            CollectionDescription { name: "medium-title".to_string(), },
            CollectionDescription { name: "medium-text".to_string(), },
        ],
    }
}

